def allQueensSafe(queens):
    rows, cols, down, up = set(), set(), set(), set()
    for r, c in queens:
        if r in rows or c in cols or (r - c) in down or (r + c) in up:
            return False
        rows.add(r)
        cols.add(c)
        down.add(r - c)
        up.add(r + c)
    return True
